// End-to-end helper for CI (macOS runners have a single virtual screen).
//
//   e2e_tool vdisplay          create a 1920x1080 virtual display to the right of the main one and keep it alive
//   e2e_tool displays          print "id x y w h" for every active display
//   e2e_tool post <x> <y>      post a mouse-moved event at (x, y), then print where the pointer ended up
//   e2e_tool where             print the pointer location
//   e2e_tool dock              print CoreDockGetRect
//
// Build: clang -fobjc-arc -framework Foundation -framework CoreGraphics -framework ApplicationServices e2e_tool.m -o e2e_tool

#import <Foundation/Foundation.h>
#import <ApplicationServices/ApplicationServices.h>
#import <CoreGraphics/CoreGraphics.h>
#import <dlfcn.h>

// Private CoreGraphics classes (macOS 11+), resolved at runtime with NSClassFromString.
@interface CGVirtualDisplayDescriptor : NSObject
@property (retain, nonatomic) dispatch_queue_t queue;
@property (retain, nonatomic) NSString *name;
@property (nonatomic) unsigned int maxPixelsWide;
@property (nonatomic) unsigned int maxPixelsHigh;
@property (nonatomic) CGSize sizeInMillimeters;
@property (nonatomic) unsigned int productID;
@property (nonatomic) unsigned int vendorID;
@property (nonatomic) unsigned int serialNum;
@property (nonatomic) CGPoint whitePoint;
@property (nonatomic) CGPoint redPrimary;
@property (nonatomic) CGPoint greenPrimary;
@property (nonatomic) CGPoint bluePrimary;
@end

@interface CGVirtualDisplayMode : NSObject
- (instancetype)initWithWidth:(unsigned int)width height:(unsigned int)height refreshRate:(double)refreshRate;
@end

@interface CGVirtualDisplaySettings : NSObject
@property (retain, nonatomic) NSArray *modes;
@property (nonatomic) unsigned int hiDPI;
@end

@interface CGVirtualDisplay : NSObject
- (instancetype)initWithDescriptor:(CGVirtualDisplayDescriptor *)descriptor;
- (BOOL)applySettings:(CGVirtualDisplaySettings *)settings;
@property (readonly, nonatomic) unsigned int displayID;
@end

static void printDisplays(void) {
    CGDirectDisplayID ids[16];
    uint32_t count = 0;
    CGGetActiveDisplayList(16, ids, &count);
    for (uint32_t i = 0; i < count; i++) {
        CGRect b = CGDisplayBounds(ids[i]);
        printf("%u %.0f %.0f %.0f %.0f%s\n", ids[i], b.origin.x, b.origin.y, b.size.width, b.size.height,
               CGDisplayIsMain(ids[i]) ? " main" : "");
    }
    fflush(stdout);
}

static CGPoint pointer(void) {
    CGEventRef event = CGEventCreate(NULL);
    CGPoint p = CGEventGetLocation(event);
    CFRelease(event);
    return p;
}

static int makeVirtualDisplay(void) {
    Class descriptorClass = NSClassFromString(@"CGVirtualDisplayDescriptor");
    Class displayClass = NSClassFromString(@"CGVirtualDisplay");
    Class settingsClass = NSClassFromString(@"CGVirtualDisplaySettings");
    Class modeClass = NSClassFromString(@"CGVirtualDisplayMode");
    if (!descriptorClass || !displayClass || !settingsClass || !modeClass) {
        fprintf(stderr, "CGVirtualDisplay API not available\n");
        return 2;
    }
    CGVirtualDisplayDescriptor *descriptor = [[descriptorClass alloc] init];
    descriptor.queue = dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_HIGH, 0);
    descriptor.name = @"DockLock E2E Display";
    descriptor.maxPixelsWide = 1920;
    descriptor.maxPixelsHigh = 1080;
    descriptor.sizeInMillimeters = CGSizeMake(527, 296);
    descriptor.productID = 0x1234;
    descriptor.vendorID = 0x3456;
    descriptor.serialNum = 0x0001;
    descriptor.whitePoint = CGPointMake(0.3125, 0.3291);
    descriptor.redPrimary = CGPointMake(0.6797, 0.3203);
    descriptor.greenPrimary = CGPointMake(0.2559, 0.6983);
    descriptor.bluePrimary = CGPointMake(0.1494, 0.0557);

    CGVirtualDisplay *display = [[displayClass alloc] initWithDescriptor:descriptor];
    if (!display) {
        fprintf(stderr, "could not create virtual display\n");
        return 3;
    }
    CGVirtualDisplaySettings *settings = [[settingsClass alloc] init];
    settings.hiDPI = 0;
    settings.modes = @[[[modeClass alloc] initWithWidth:1920 height:1080 refreshRate:60]];
    if (![display applySettings:settings]) {
        fprintf(stderr, "applySettings failed\n");
        return 4;
    }
    CGDirectDisplayID vid = display.displayID;
    printf("created %u\n", vid);
    fflush(stdout);
    sleep(2);

    // Put it to the right of the main display, top-aligned, so both bottom edges are free.
    CGRect main = CGDisplayBounds(CGMainDisplayID());
    CGDisplayConfigRef config;
    if (CGBeginDisplayConfiguration(&config) == kCGErrorSuccess) {
        CGConfigureDisplayOrigin(config, vid, (int32_t)main.size.width, 0);
        CGCompleteDisplayConfiguration(config, kCGConfigureForSession);
    }
    sleep(2);
    printDisplays();
    printf("ready\n");
    fflush(stdout);
    // Keep the display alive until killed.
    while (1) { CFRunLoopRunInMode(kCFRunLoopDefaultMode, 60, false); }
    (void)display;
    return 0;
}

int main(int argc, const char *argv[]) {
    @autoreleasepool {
        if (argc < 2) { fprintf(stderr, "usage: e2e_tool vdisplay|displays|post x y|where|dock\n"); return 1; }
        NSString *cmd = @(argv[1]);
        if ([cmd isEqualToString:@"vdisplay"]) return makeVirtualDisplay();
        if ([cmd isEqualToString:@"displays"]) { printDisplays(); return 0; }
        if ([cmd isEqualToString:@"where"]) { CGPoint p = pointer(); printf("%.1f %.1f\n", p.x, p.y); return 0; }
        if ([cmd isEqualToString:@"post"] && argc >= 4) {
            CGPoint target = CGPointMake(atof(argv[2]), atof(argv[3]));
            for (int i = 0; i < 3; i++) {
                CGEventRef move = CGEventCreateMouseEvent(NULL, kCGEventMouseMoved, target, kCGMouseButtonLeft);
                CGEventPost(kCGHIDEventTap, move);
                CFRelease(move);
                usleep(80000);
            }
            usleep(200000);
            CGPoint p = pointer();
            printf("%.1f %.1f\n", p.x, p.y);
            return 0;
        }
        if ([cmd isEqualToString:@"windows"] && argc >= 3) {
            // Window numbers of on-screen windows owned by a process name (largest first).
            NSArray *list = CFBridgingRelease(CGWindowListCopyWindowInfo(kCGWindowListOptionOnScreenOnly, kCGNullWindowID));
            NSMutableArray *matches = [NSMutableArray array];
            for (NSDictionary *w in list) {
                if (![w[(id)kCGWindowOwnerName] isEqualToString:@(argv[2])]) continue;
                if ([w[(id)kCGWindowLayer] intValue] != 0) continue;
                CGRect b; CGRectMakeWithDictionaryRepresentation((CFDictionaryRef)w[(id)kCGWindowBounds], &b);
                [matches addObject:@[w[(id)kCGWindowNumber], @(b.size.width * b.size.height)]];
            }
            [matches sortUsingComparator:^NSComparisonResult(NSArray *a, NSArray *b) { return [b[1] compare:a[1]]; }];
            for (NSArray *m in matches) printf("%d\n", [m[0] intValue]);
            return 0;
        }
        if ([cmd isEqualToString:@"dock"]) {
            typedef void (*GetRect)(CGRect *);
            GetRect getRect = (GetRect)dlsym(RTLD_DEFAULT, "CoreDockGetRect");
            if (!getRect) { printf("unavailable\n"); return 0; }
            CGRect r; getRect(&r);
            printf("%.0f %.0f %.0f %.0f\n", r.origin.x, r.origin.y, r.size.width, r.size.height);
            return 0;
        }
        fprintf(stderr, "unknown command\n");
        return 1;
    }
}

import AppKit
import ApplicationServices

/// Read-mostly access to the Dock: where it is, which edge, auto-hide, and the Spaces setting.
///
/// Uses the `CoreDock*` functions exported by HIServices (looked up at runtime, so a missing
/// symbol degrades gracefully) and falls back to the Dock's accessibility tree and defaults.
enum DockInspector {
    // MARK: CoreDock (private, resolved with dlsym)

    private typealias GetRectFn = @convention(c) (UnsafeMutablePointer<CGRect>) -> Void
    private typealias GetOrientationFn = @convention(c) (UnsafeMutablePointer<Int32>, UnsafeMutablePointer<Int32>) -> Void
    private typealias GetAutoHideFn = @convention(c) () -> Bool
    private typealias SetAutoHideFn = @convention(c) (Bool) -> Void

    private static let handle: UnsafeMutableRawPointer? = dlopen(
        "/System/Library/Frameworks/ApplicationServices.framework/ApplicationServices", RTLD_LAZY)

    private static func symbol<T>(_ name: String, as type: T.Type) -> T? {
        _ = handle
        guard let pointer = dlsym(UnsafeMutableRawPointer(bitPattern: -2), name) else { return nil } // RTLD_DEFAULT
        return unsafeBitCast(pointer, to: type)
    }

    private static let getRect = symbol("CoreDockGetRect", as: GetRectFn.self)
    private static let getOrientation = symbol("CoreDockGetOrientationAndPinning", as: GetOrientationFn.self)
    private static let getAutoHide = symbol("CoreDockGetAutoHideEnabled", as: GetAutoHideFn.self)
    private static let setAutoHide = symbol("CoreDockSetAutoHideEnabled", as: SetAutoHideFn.self)

    // MARK: Queries

    /// The Dock's frame in CG global coordinates.
    static func dockFrame() -> CGRect? {
        if let getRect {
            var rect = CGRect.zero
            getRect(&rect)
            if rect.width > 1, rect.height > 1 { return rect }
        }
        return accessibilityDockFrame()
    }

    static func edge() -> DockEdge {
        if let getOrientation {
            var orientation: Int32 = 0
            var pinning: Int32 = 0
            getOrientation(&orientation, &pinning)
            if let edge = DockEdge(coreDockOrientation: Int(orientation)) { return edge }
        }
        if let value = CFPreferencesCopyAppValue("orientation" as CFString, "com.apple.dock" as CFString) as? String,
           let edge = DockEdge(defaultsValue: value) {
            return edge
        }
        return .bottom
    }

    static func isAutoHideEnabled() -> Bool {
        if let getAutoHide { return getAutoHide() }
        return (CFPreferencesCopyAppValue("autohide" as CFString, "com.apple.dock" as CFString) as? Bool) ?? false
    }

    @discardableResult
    static func setAutoHideEnabled(_ enabled: Bool) -> Bool {
        if let setAutoHide {
            setAutoHide(enabled)
            return true
        }
        // Fallback: AppleScript through System Events.
        let script = "tell application \"System Events\" to set autohide of dock preferences to \(enabled)"
        var error: NSDictionary?
        NSAppleScript(source: script)?.executeAndReturnError(&error)
        return error == nil
    }

    /// "Displays have separate Spaces" (System Settings › Desktop & Dock). On by default.
    static func displaysHaveSeparateSpaces() -> Bool {
        CFPreferencesAppSynchronize("com.apple.spaces" as CFString)
        let spans = CFPreferencesCopyAppValue("spans-displays" as CFString, "com.apple.spaces" as CFString)
        if let flag = spans as? Bool { return !flag }
        if let number = spans as? NSNumber { return number.intValue == 0 }
        return true
    }

    static var dockApplication: NSRunningApplication? {
        NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.dock").first
    }

    /// Restarts the Dock (launchd relaunches it immediately).
    static func restartDock() {
        let task = Process()
        task.executableURL = URL(fileURLWithPath: "/usr/bin/killall")
        task.arguments = ["Dock"]
        try? task.run()
    }

    // MARK: Accessibility fallback

    private static func accessibilityDockFrame() -> CGRect? {
        guard AXIsProcessTrusted(), let dock = dockApplication else { return nil }
        let app = AXUIElementCreateApplication(dock.processIdentifier)
        AXUIElementSetMessagingTimeout(app, 0.25)
        guard let children = AX.children(of: app) else { return nil }
        for child in children where AX.string(child, kAXRoleAttribute) == (kAXListRole as String) {
            if let frame = AX.frame(of: child), frame.width > 1, frame.height > 1 { return frame }
        }
        return nil
    }
}

/// Small helpers over the AXUIElement C API.
enum AX {
    static func value(_ element: AXUIElement, _ attribute: String) -> CFTypeRef? {
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, attribute as CFString, &value) == .success else { return nil }
        return value
    }

    static func string(_ element: AXUIElement, _ attribute: String) -> String? {
        value(element, attribute) as? String
    }

    static func element(_ element: AXUIElement, _ attribute: String) -> AXUIElement? {
        guard let raw = value(element, attribute), CFGetTypeID(raw) == AXUIElementGetTypeID() else { return nil }
        return (raw as! AXUIElement)
    }

    static func children(of element: AXUIElement) -> [AXUIElement]? {
        guard let raw = value(element, kAXChildrenAttribute as String) as? [AnyObject] else { return nil }
        return raw.compactMap { item in
            CFGetTypeID(item) == AXUIElementGetTypeID() ? (item as! AXUIElement) : nil
        }
    }

    static func frame(of element: AXUIElement) -> CGRect? {
        guard let positionRef = value(element, kAXPositionAttribute as String),
              let sizeRef = value(element, kAXSizeAttribute as String),
              CFGetTypeID(positionRef) == AXValueGetTypeID(),
              CFGetTypeID(sizeRef) == AXValueGetTypeID() else { return nil }
        var position = CGPoint.zero
        var size = CGSize.zero
        guard AXValueGetValue(positionRef as! AXValue, .cgPoint, &position),
              AXValueGetValue(sizeRef as! AXValue, .cgSize, &size) else { return nil }
        return CGRect(origin: position, size: size)
    }

    /// Frame (CG global coordinates) of the focused window of the frontmost app, or of `pid`.
    static func focusedWindowFrame(pid: pid_t? = nil) -> CGRect? {
        guard AXIsProcessTrusted() else { return nil }
        let appElement: AXUIElement
        if let pid {
            appElement = AXUIElementCreateApplication(pid)
        } else {
            let systemWide = AXUIElementCreateSystemWide()
            guard let focusedApp = element(systemWide, kAXFocusedApplicationAttribute as String) else { return nil }
            appElement = focusedApp
        }
        AXUIElementSetMessagingTimeout(appElement, 0.3)
        let window = element(appElement, kAXFocusedWindowAttribute as String)
            ?? element(appElement, kAXMainWindowAttribute as String)
        guard let window, let frame = frame(of: window), frame.width >= 80, frame.height >= 60 else { return nil }
        return frame
    }
}

import Foundation
#if canImport(CoreGraphics)
import CoreGraphics
#endif
import XCTest
@testable import DockLockCore

final class DisplayLayoutTests: XCTestCase {
    func testOrderingAndArrangementKey() {
        let layout = DisplayLayout([Fixtures.dell, Fixtures.laptop, Fixtures.studio])
        XCTAssertEqual(layout.displays.map(\.uuid), ["AAAA", "BBBB", "CCCC"])
        XCTAssertEqual(layout.arrangementKey, "AAAA+BBBB+CCCC")
        XCTAssertEqual(DisplayLayout([Fixtures.studio, Fixtures.laptop]).arrangementKey,
                       DisplayLayout([Fixtures.laptop, Fixtures.studio]).arrangementKey)
        XCTAssertEqual(layout.main?.uuid, "AAAA")
    }

    func testNameResolution() {
        let layout = Fixtures.three
        XCTAssertEqual(layout.display(named: "Studio Display")?.uuid, "BBBB")
        XCTAssertEqual(layout.display(named: "studio display")?.uuid, "BBBB")
        XCTAssertEqual(layout.display(named: "dell")?.uuid, "CCCC", "unique partial match")
        XCTAssertEqual(layout.display(named: "main")?.uuid, "AAAA")
        XCTAssertEqual(layout.display(named: "builtin")?.uuid, "AAAA")
        XCTAssertEqual(layout.display(named: "#3")?.uuid, "CCCC")
        XCTAssertEqual(layout.display(named: "cccc")?.uuid, "CCCC")
        XCTAssertEqual(layout.display(named: "2")?.uuid, "BBBB", "numeric display ID")
        XCTAssertNil(layout.display(named: "Projector"))
        XCTAssertNil(layout.display(named: "d"), "ambiguous partial match")
    }

    func testIdenticalMonitorsGetDistinctNames() {
        var twin = Fixtures.dell
        twin.uuid = "EEEE"
        twin.id = 5
        twin.frame = CGRect(x: 6848, y: -323, width: 2560, height: 1440)
        let layout = DisplayLayout([Fixtures.laptop, Fixtures.dell, twin])
        XCTAssertEqual(layout.displayName(for: Fixtures.dell), "DELL U2720Q (1)")
        XCTAssertEqual(layout.displayName(for: twin), "DELL U2720Q (2)")
        XCTAssertEqual(layout.display(named: "DELL U2720Q (2)")?.uuid, "EEEE")
    }

    func testContainmentAndNearest() {
        let layout = Fixtures.sideBySide
        XCTAssertEqual(layout.display(containing: CGPoint(x: 1, y: 1))?.uuid, "AAAA")
        XCTAssertEqual(layout.display(containing: CGPoint(x: 1728, y: 10))?.uuid, "BBBB", "seam belongs to the right display")
        XCTAssertNil(layout.display(containing: CGPoint(x: 100, y: -100)))
        XCTAssertEqual(layout.nearestDisplay(to: CGPoint(x: 100, y: -100))?.uuid, "AAAA")
        XCTAssertEqual(layout.display(bestMatching: CGRect(x: 1600, y: 100, width: 400, height: 300))?.uuid, "BBBB")
    }

    func testAdjacency() {
        let layout = Fixtures.three
        XCTAssertEqual(layout.adjacent(to: Fixtures.laptop, direction: .right)?.uuid, "BBBB")
        XCTAssertEqual(layout.adjacent(to: Fixtures.studio, direction: .right)?.uuid, "CCCC")
        XCTAssertEqual(layout.adjacent(to: Fixtures.studio, direction: .left)?.uuid, "AAAA")
        XCTAssertNil(layout.adjacent(to: Fixtures.laptop, direction: .left))
        XCTAssertNil(layout.adjacent(to: Fixtures.laptop, direction: .down))

        let stacked = Fixtures.stacked
        XCTAssertEqual(stacked.adjacent(to: Fixtures.laptop, direction: .up)?.uuid, "DDDD")
        XCTAssertEqual(stacked.adjacent(to: Fixtures.above, direction: .down)?.uuid, "AAAA")
        XCTAssertNil(stacked.adjacent(to: Fixtures.laptop, direction: .right))
    }
}

final class DockLocatorTests: XCTestCase {
    func testVisibleBottomDock() {
        let frame = CGRect(x: 326, y: 1039, width: 1075, height: 78) // measured on a 1728×1117 laptop
        XCTAssertEqual(DockLocator.display(forDockFrame: frame, edge: .bottom, in: Fixtures.sideBySide)?.uuid, "AAAA")
        let onStudio = CGRect(x: 2500, y: 1117 - 70, width: 900, height: 70)
        XCTAssertEqual(DockLocator.display(forDockFrame: onStudio, edge: .bottom, in: Fixtures.sideBySide)?.uuid, "BBBB")
    }

    func testAutoHiddenDockBelowTheEdge() {
        let hidden = CGRect(x: 2500, y: 1117, width: 900, height: 70)
        XCTAssertEqual(DockLocator.display(forDockFrame: hidden, edge: .bottom, in: Fixtures.sideBySide)?.uuid, "BBBB")
    }

    func testVerticalDock() {
        let left = CGRect(x: 0, y: 200, width: 70, height: 700)
        XCTAssertEqual(DockLocator.display(forDockFrame: left, edge: .left, in: Fixtures.sideBySide)?.uuid, "AAAA")
        let right = CGRect(x: 4288 - 70, y: 0, width: 70, height: 700)
        XCTAssertEqual(DockLocator.display(forDockFrame: right, edge: .right, in: Fixtures.sideBySide)?.uuid, "BBBB")
    }

    func testRejectsEmptyFrames() {
        XCTAssertNil(DockLocator.display(forDockFrame: .zero, edge: .bottom, in: Fixtures.sideBySide))
        XCTAssertNil(DockLocator.display(forDockFrame: CGRect(x: 90000, y: 90000, width: 500, height: 60),
                                         edge: .bottom, in: Fixtures.sideBySide))
    }
}

final class PolicyTests: XCTestCase {
    let settings = DockLockSettings()

    func testDefaultPreferencesKeepDockWhereItIs() {
        let prefs = DockPolicy.defaultPreferences(for: Fixtures.three, dockDisplayUUID: "BBBB")
        XCTAssertEqual(prefs.allowed, ["BBBB"])
        XCTAssertEqual(prefs.home, "BBBB")
        let fallback = DockPolicy.defaultPreferences(for: Fixtures.three, dockDisplayUUID: nil)
        XCTAssertEqual(fallback.allowed, ["AAAA"])
        XCTAssertEqual(fallback.names["CCCC"], "DELL U2720Q")
    }

    func testGuardedDisplays() {
        let prefs = ArrangementPreferences(allowed: ["AAAA"], home: "AAAA")
        var runtime = RuntimeState()
        XCTAssertEqual(DockPolicy.guardedDisplays(settings: settings, layout: Fixtures.three, preferences: prefs, runtime: runtime),
                       ["BBBB", "CCCC"])
        runtime.temporarilyAllowed = ["CCCC"]
        XCTAssertEqual(DockPolicy.guardedDisplays(settings: settings, layout: Fixtures.three, preferences: prefs, runtime: runtime),
                       ["BBBB"])
        runtime.exclusiveTarget = "BBBB"
        XCTAssertEqual(DockPolicy.guardedDisplays(settings: settings, layout: Fixtures.three, preferences: prefs, runtime: runtime),
                       ["AAAA", "CCCC"], "a manual placement holds the Dock on that display only")
        runtime.exclusiveTarget = "GONE"
        XCTAssertEqual(DockPolicy.guardedDisplays(settings: settings, layout: Fixtures.three, preferences: prefs, runtime: runtime),
                       ["BBBB"], "a disconnected exclusive target is ignored")
        runtime.exclusiveTarget = nil
        runtime.hideDock = true
        XCTAssertEqual(DockPolicy.guardedDisplays(settings: settings, layout: Fixtures.three, preferences: prefs, runtime: runtime),
                       ["AAAA", "BBBB", "CCCC"])
        runtime.paused = true
        XCTAssertTrue(DockPolicy.guardedDisplays(settings: settings, layout: Fixtures.three, preferences: prefs, runtime: runtime).isEmpty)

        var disabled = settings
        disabled.isEnabled = false
        XCTAssertTrue(DockPolicy.guardedDisplays(settings: disabled, layout: Fixtures.three, preferences: prefs,
                                                 runtime: RuntimeState()).isEmpty)
    }

    func testSingleDisplayOnlyGuardedWhenHiding() {
        let single = DisplayLayout([Fixtures.laptop])
        let prefs = ArrangementPreferences(allowed: ["AAAA"])
        XCTAssertTrue(DockPolicy.guardedDisplays(settings: settings, layout: single, preferences: prefs,
                                                 runtime: RuntimeState()).isEmpty)
        XCTAssertEqual(DockPolicy.guardedDisplays(settings: settings, layout: single, preferences: prefs,
                                                  runtime: RuntimeState(hideDock: true)), ["AAAA"])
    }

    func testNoAllowedDisplayHidesDockEverywhere() {
        let prefs = ArrangementPreferences(allowed: [])
        XCTAssertEqual(DockPolicy.guardedDisplays(settings: settings, layout: Fixtures.sideBySide, preferences: prefs,
                                                  runtime: RuntimeState()), ["AAAA", "BBBB"])
        XCTAssertNil(DockPolicy.homeTarget(dockDisplayUUID: "BBBB", settings: settings, layout: Fixtures.sideBySide,
                                           preferences: prefs, runtime: RuntimeState()))
    }

    func testHomeTarget() {
        let prefs = ArrangementPreferences(allowed: ["AAAA", "CCCC"], home: "CCCC")
        let rt = RuntimeState()
        XCTAssertNil(DockPolicy.homeTarget(dockDisplayUUID: "AAAA", settings: settings, layout: Fixtures.three,
                                           preferences: prefs, runtime: rt), "already on an allowed display")
        XCTAssertEqual(DockPolicy.homeTarget(dockDisplayUUID: "BBBB", settings: settings, layout: Fixtures.three,
                                             preferences: prefs, runtime: rt)?.uuid, "CCCC")
        let noHome = ArrangementPreferences(allowed: ["CCCC", "AAAA"], home: "ZZZZ")
        XCTAssertEqual(DockPolicy.homeTarget(dockDisplayUUID: "BBBB", settings: settings, layout: Fixtures.three,
                                             preferences: noHome, runtime: rt)?.uuid, "AAAA", "main display first")
        XCTAssertNil(DockPolicy.homeTarget(dockDisplayUUID: "BBBB", settings: settings, layout: Fixtures.three,
                                           preferences: prefs, runtime: RuntimeState(hideDock: true)))
        XCTAssertEqual(DockPolicy.homeTarget(dockDisplayUUID: "AAAA", settings: settings, layout: Fixtures.three,
                                             preferences: prefs, runtime: RuntimeState(exclusiveTarget: "BBBB"))?.uuid, "BBBB")
    }

    func testFollowTarget() {
        var s = settings
        s.mode = .followsMouse
        let prefs = ArrangementPreferences(allowed: ["AAAA", "BBBB"])
        XCTAssertEqual(DockPolicy.followTarget(candidate: Fixtures.studio, dockDisplayUUID: "AAAA", settings: s,
                                               layout: Fixtures.three, preferences: prefs, runtime: RuntimeState())?.uuid, "BBBB")
        XCTAssertNil(DockPolicy.followTarget(candidate: Fixtures.dell, dockDisplayUUID: "AAAA", settings: s,
                                             layout: Fixtures.three, preferences: prefs, runtime: RuntimeState()),
                     "not allowed")
        XCTAssertNil(DockPolicy.followTarget(candidate: Fixtures.laptop, dockDisplayUUID: "AAAA", settings: s,
                                             layout: Fixtures.three, preferences: prefs, runtime: RuntimeState()),
                     "already there")
        s.mode = .lock
        XCTAssertNil(DockPolicy.followTarget(candidate: Fixtures.studio, dockDisplayUUID: "AAAA", settings: s,
                                             layout: Fixtures.three, preferences: prefs, runtime: RuntimeState()))
    }

    func testGuardConfigurationDropsBypassWhileHiding() {
        var s = settings
        s.bypassModifiers = [.option]
        let prefs = ArrangementPreferences(allowed: ["AAAA"])
        let normal = DockPolicy.guardConfiguration(settings: s, layout: Fixtures.sideBySide, preferences: prefs,
                                                   runtime: RuntimeState(), dockEdge: .bottom)
        XCTAssertEqual(normal.bypassModifiers, [.option])
        XCTAssertEqual(normal.zones.map(\.displayUUID), ["BBBB"])
        let hiding = DockPolicy.guardConfiguration(settings: s, layout: Fixtures.sideBySide, preferences: prefs,
                                                   runtime: RuntimeState(hideDock: true), dockEdge: .bottom)
        XCTAssertEqual(hiding.bypassModifiers, [])
        XCTAssertEqual(Set(hiding.zones.map(\.displayUUID)), ["AAAA", "BBBB"])
    }

    func testRelocationRateLimit() {
        let now = Date()
        let recent = (0..<6).map { now.addingTimeInterval(-Double($0) * 10) }
        XCTAssertFalse(DockPolicy.allowsAutomaticRelocation(history: recent, now: now))
        let old = (0..<6).map { now.addingTimeInterval(-400 - Double($0)) }
        XCTAssertTrue(DockPolicy.allowsAutomaticRelocation(history: old, now: now))
    }
}

import AppKit

/// In-app language choice. macOS reads `AppleLanguages` from the app's own defaults at launch,
/// so a change applies after DockLock restarts. (The same choice is available in
/// System Settings › General › Language & Region › Applications.)
enum AppLanguage {
    struct Option: Hashable {
        let code: String
        let name: String
    }

    /// Languages DockLock ships translations for, with their names in that language.
    static let supported: [Option] = [
        Option(code: "en", name: "English"),
        Option(code: "zh-Hans", name: "简体中文"),
        Option(code: "zh-Hant", name: "繁體中文"),
        Option(code: "ja", name: "日本語"),
        Option(code: "ko", name: "한국어"),
        Option(code: "de", name: "Deutsch"),
        Option(code: "fr", name: "Français"),
        Option(code: "es", name: "Español"),
        Option(code: "pt-BR", name: "Português (Brasil)"),
        Option(code: "ru", name: "Русский"),
    ]

    /// The language chosen inside DockLock, or nil to follow the system.
    static var override: String? {
        guard let id = Bundle.main.bundleIdentifier,
              let languages = UserDefaults.standard.persistentDomain(forName: id)?["AppleLanguages"] as? [String] else {
            return nil
        }
        return languages.first
    }

    static func set(_ code: String?) {
        if let code {
            UserDefaults.standard.set([code], forKey: "AppleLanguages")
        } else {
            UserDefaults.standard.removeObject(forKey: "AppleLanguages")
        }
    }

    /// Starts a fresh copy once this one has quit.
    static func relaunch() {
        let task = Process()
        task.executableURL = URL(fileURLWithPath: "/bin/sh")
        task.arguments = ["-c", "sleep 1; /usr/bin/open \"$0\"", Bundle.main.bundlePath]
        try? task.run()
        NSApp.terminate(nil)
    }
}

