        let json = #"{"mode":"follows-mouse","guardBand":"wide","hotKeys":[{"action":"moveLeft","keyCode":0,"modifiers":1,"enabled":true}]}"#
        let decoded = try DockLockSettings.decode(Data(json.utf8))
        XCTAssertEqual(decoded.mode, .followsMouse)
