enum Permissions {
    static var isAccessibilityTrusted: Bool { AXIsProcessTrusted() }

    /// Shows the system prompt that offers to open Privacy & Security › Accessibility.
    static func requestAccessibility() {
        let key = kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String
        _ = AXIsProcessTrustedWithOptions([key: true] as CFDictionary)
    }

    static func openAccessibilitySettings() {
        if let url = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility") {
            NSWorkspace.shared.open(url)
        }
    }

    static func openDesktopAndDockSettings() {
        let candidates = ["x-apple.systempreferences:com.apple.Desktop-Settings.extension",
                          "x-apple.systempreferences:com.apple.preference.dock"]
        for candidate in candidates {
            if let url = URL(string: candidate), NSWorkspace.shared.open(url) { return }
        }
    }

    static func openDisplaysSettings() {
        if let url = URL(string: "x-apple.systempreferences:com.apple.Displays-Settings.extension") {
            NSWorkspace.shared.open(url)
        }
    }
}

enum LoginItem {
    static var isEnabled: Bool { SMAppService.mainApp.status == .enabled }
    static var needsApproval: Bool { SMAppService.mainApp.status == .requiresApproval }

    static func set(_ enabled: Bool) -> Bool {
        do {
            if enabled {
                try SMAppService.mainApp.register()
            } else {
                try SMAppService.mainApp.unregister()
            }
            return true
        } catch {
            NSLog("DockLock: could not change login item: \(error.localizedDescription)")
            return false
        }
    }
}

enum Notifier {
    static func post(title: String, body: String) {
        let center = UNUserNotificationCenter.current()
        center.requestAuthorization(options: [.alert]) { granted, _ in
            guard granted else { return }
            let content = UNMutableNotificationContent()
            content.title = title
            content.body = body
            center.add(UNNotificationRequest(identifier: UUID().uuidString, content: content, trigger: nil))
        }
    }
}

/// Persists `DockLockSettings` as one JSON document in the app's defaults.
enum SettingsStore {
    private static let key = "settings.v1"

    static func load() -> DockLockSettings {
        guard let data = UserDefaults.standard.data(forKey: key),
              let settings = try? DockLockSettings.decode(data) else { return DockLockSettings() }
        return settings
    }

    static func save(_ settings: DockLockSettings) {
        guard let data = try? settings.encoded() else { return }
        UserDefaults.standard.set(data, forKey: key)
    }

    static func reset() {
        UserDefaults.standard.removeObject(forKey: key)
    }

    /// Remembers that DockLock (not the user) switched on Dock auto-hide, so it can be restored
    /// even after a crash.
    static var autoHideEnabledByDockLock: Bool {
        get { UserDefaults.standard.bool(forKey: "autoHideEnabledByDockLock") }
        set { UserDefaults.standard.set(newValue, forKey: "autoHideEnabledByDockLock") }
    }
}

/// Decides whether the Dock should currently be hidden for a meeting / screen sharing.
final class MeetingMonitor {
    /// Called with a human-readable reason while hiding is needed, nil otherwise.
    var onChange: ((String?) -> Void)?
    private(set) var reason: String?

    private var watchScreenSharing = false
    private var bundleIDs: Set<String> = []
    private var timer: Timer?
    private var observers: [NSObjectProtocol] = []

    init() {
        let center = NSWorkspace.shared.notificationCenter
        for name in [NSWorkspace.didLaunchApplicationNotification, NSWorkspace.didTerminateApplicationNotification] {
            observers.append(center.addObserver(forName: name, object: nil, queue: .main) { [weak self] _ in
                self?.evaluate()
            })
        }
    }

    deinit {
        observers.forEach { NSWorkspace.shared.notificationCenter.removeObserver($0) }
    }

    func configure(screenSharing: Bool, bundleIDs: [String]) {
        watchScreenSharing = screenSharing
        self.bundleIDs = Set(bundleIDs)
        timer?.invalidate()
        timer = nil
        if screenSharing {
            let timer = Timer(timeInterval: 2, repeats: true) { [weak self] _ in self?.evaluate() }
            timer.tolerance = 0.5
            RunLoop.main.add(timer, forMode: .common)
            self.timer = timer
        }
        evaluate()
    }

    func evaluate() {
        var newReason: String?
        if watchScreenSharing && ScreenCaptureDetector.isCapturing() {
            newReason = L("Screen sharing or recording")
        } else if !bundleIDs.isEmpty,
                  let app = NSWorkspace.shared.runningApplications.first(where: { bundleIDs.contains($0.bundleIdentifier ?? "") }) {
            newReason = app.localizedName ?? app.bundleIdentifier
        }
        if newReason != reason {
            reason = newReason
            onChange?(newReason)
        }
    }
}

#!/usr/bin/env python3
"""Fails when a user-facing string in the app is missing from any translation.

Collects every L("…") / LF("…") key and every App Intents title/description/parameter title,
and checks every App/Resources/<language>.lproj/Localizable.strings: all keys present and the same
format placeholders as the English text.
"""
import glob
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
STRINGS = os.path.join(ROOT, "App", "Resources", "zh-Hans.lproj", "Localizable.strings")
LITERAL = r'"((?:[^"\\]|\\.)*)"'


def swift_unescape(text):
    text = re.sub(r"\\u\{([0-9A-Fa-f]+)\}", lambda m: chr(int(m.group(1), 16)), text)
    return text.replace('\\"', '"').replace("\\\\", "\\")


def code_keys():
    keys = set()
    for path in glob.glob(os.path.join(ROOT, "App", "Sources", "**", "*.swift"), recursive=True):
        source = open(path, encoding="utf-8").read()
        keys.update(re.findall(r"\bLF?\(\s*" + LITERAL, source))
        # LF(condition ? "a" : "b", …) and `format = "…"` variables passed to LF.
        for a, b in re.findall(r"LF\([^\"\n]*\?\s*" + LITERAL + r"\s*:\s*" + LITERAL, source):
            keys.update([a, b])
        keys.update(re.findall(r"format = " + LITERAL, source))
        keys.update(re.findall(r'NSLocalizedString\(\s*' + LITERAL, source))
        if "/Intents/" in path:
            keys.update(re.findall(r"(?:title: LocalizedStringResource = |IntentDescription\(|@Parameter\(title: |"
                                   r"TypeDisplayRepresentation = |\.\w+: )" + LITERAL, source))
    return {swift_unescape(k) for k in keys}


SPECIFIER = re.compile(r"%(?:\d+\$)?l{0,2}[@dufs]")


def parse_strings(path):
    text = open(path, encoding="utf-8").read()
    pairs = re.findall(r'^' + LITERAL + r'\s*=\s*' + LITERAL + r'\s*;', text, flags=re.M)
    return {swift_unescape(k): swift_unescape(v) for k, v in pairs}


def translated_keys(language="zh-Hans"):
    return set(parse_strings(os.path.join(ROOT, "App", "Resources", f"{language}.lproj", "Localizable.strings")))


def languages():
    folders = glob.glob(os.path.join(ROOT, "App", "Resources", "*.lproj"))
    return sorted(os.path.basename(f)[:-6] for f in folders if not f.endswith("en.lproj"))


def main():
    keys = code_keys()
    failed = False
    for language in languages():
        table = parse_strings(os.path.join(ROOT, "App", "Resources", f"{language}.lproj", "Localizable.strings"))
        missing = sorted(keys - set(table))
        stale = sorted(set(table) - keys)
        wrong = sorted(k for k in keys & set(table)
                       if sorted(SPECIFIER.findall(k)) != sorted(SPECIFIER.findall(table[k])))
        if missing:
            failed = True
            print(f"[{language}] missing translations:")
            for key in missing:
                print(f'  "{key}"')
        if wrong:
            failed = True
            print(f"[{language}] placeholders (%@, %ld, …) differ from the English text:")
            for key in wrong:
                print(f'  "{key}"  ->  "{table[key]}"')
        if stale:
            print(f"[{language}] warning: {len(stale)} unused entries (safe to delete):")
            for key in stale:
                print(f'  "{key}"')
    if failed:
        return 1
    print(f"Localization OK: {len(keys)} strings in {len(languages())} languages ({', '.join(languages())}).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
